    [Fact]
    public void LoadYamlInput()
    {
        string yamlData = """
sessionId: sample
turnId: sample
invocationId: sample
iteration: 1
messages: []
contextState: {}

""";

        var instance = ContextRequest.FromYaml(yamlData);

        Assert.NotNull(instance);
        Assert.Equal("sample", instance.SessionId);
        Assert.Equal("sample", instance.TurnId);
        Assert.Equal("sample", instance.InvocationId);
        Assert.Equal(1, instance.Iteration);
    }

