    [Fact]
    public void RoundtripJson()
    {
        // Test that FromJson -> ToJson -> FromJson produces equivalent data
        string jsonData = """
{
  "sessionId": "sample",
  "turnId": "sample",
  "invocationId": "sample",
  "iteration": 1,
  "messages": [],
  "contextState": {}
}
""";

        var original = ContextRequest.FromJson(jsonData);
        Assert.NotNull(original);

        var json = original.ToJson();
        Assert.False(string.IsNullOrEmpty(json));

        var reloaded = ContextRequest.FromJson(json);
        Assert.NotNull(reloaded);
        Assert.Equal("sample", reloaded.SessionId);
        Assert.Equal("sample", reloaded.TurnId);
        Assert.Equal("sample", reloaded.InvocationId);
        Assert.Equal(1, reloaded.Iteration);
    }

